LE primeline_referencias_backup.funcoes AS SELECT oid::regprocedure::text signature,pg_get_functiondef(oid) definition,proacl,proowner,proconfig FROM pg_proc WHERE oid=ANY(ARRAY['folha_privado.diaria_pessoal(uuid,date)'::regprocedure,'folha_privado.diaria_factos(uuid,date)'::regprocedure,'folha_privado.diaria_recalcular(uuid,date,uuid)'::regprocedure,'folha_privado.conferencia_calcular(uuid,date)'::regprocedure,'folha_privado.payroll_facts(uuid,date)'::regprocedure,'public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)'::regprocedure,'public.fn_folha_conferencia_v3(text,jsonb,boolean,text)'::regprocedure,'public.fn_folha_dia_normal_v3(jsonb,boolean,text)'::regprocedure,'public.fn_folha_faltou_v2(text,jsonb,boolean,text)'::regprocedure,'public.fn_folha_externos_confirmar_v3(jsonb,boolean,text)'::regprocedure,'public.fn_folha_destino_operar_v3(jsonb,boolean,text)'::regprocedure]::oid[]);DO $copy$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['public.folha_registos','public.folha_avaliacoes_diarias','public.folha_historico','public.folha_gestao_historico','public.folha_conferencias_mensais','public.folha_conferencia_historico','public.folha_vencimentos','public.folha_he','public.ausencias','public.colaboradores','public.quadro_equipa_permanencias','public.quadro_pessoal_alocacao','public.folha_externos_confirmacoes','folha_privado.operacoes'] LOOP EXECUTE format('INSERT INTO primeline_referencias_backup.dados SELECT %L,coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',n,n::regclass);END LOOP;END $copy$;REVOKE ALL ON ALL TABLES IN SCHEMA primeline_referencias_backup FROM PUBLIC,anon,authenticated,service_role;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_referencias_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_referencias_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_referencias_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_referencias_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_referencias_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;COMMIT;
